use quantum_ecc::{circuit::{Op,OperationType as K,QubitId,BitId},sim::Simulator};
use sha3::digest::XofReader;
struct Reader{word:u64,calls:usize} impl XofReader for Reader{fn read(&mut self,b:&mut[u8]){assert_eq!(b.len(),8);b.copy_from_slice(&self.word.to_le_bytes());self.calls+=1;}}
fn op(k:K,qs:&[u64],bit:Option<u64>)->Op{let mut o=Op::empty();o.kind=k;match k{K::CX|K::CZ|K::Swap=>{o.q_control1=QubitId(qs[0]);o.q_target=QubitId(qs[1]);},K::CCX|K::CCZ=>{o.q_control1=QubitId(qs[0]);o.q_control2=QubitId(qs[1]);o.q_target=QubitId(qs[2]);},K::X|K::Z|K::R|K::Hmr=>{o.q_target=QubitId(qs[0]);},_=>{}}if k==K::Hmr{o.c_target=BitId(bit.unwrap());}else if let Some(b)=bit{o.c_condition=BitId(b);}o.validate();o}
fn cx(a:u64,t:u64)->Op{op(K::CX,&[a,t],None)}fn ccx(a:u64,b:u64,t:u64)->Op{op(K::CCX,&[a,b,t],None)}
fn run(ops:&[Op],q:&[u64],m:u64,base:u64,phase:u64,rng:u64)->(Vec<u64>,Vec<u64>,u64,usize){let mut r=Reader{word:rng,calls:0};let mut sim=Simulator::new(8,4,&mut r);for(i,v)in q.iter().enumerate(){*sim.qubit_mut(QubitId(i as u64))=*v;}*sim.bit_mut(BitId(0))=m;*sim.bit_mut(BitId(1))=base;sim.phase=phase;sim.apply_iter(ops.iter());let res=((0..8).map(|i|sim.qubit(QubitId(i))).collect(),(0..4).map(|i|sim.bit(BitId(i))).collect(),sim.phase);drop(sim);(res.0,res.1,res.2,r.calls)}
fn scoped(body:Vec<Op>)->Vec<Op>{[vec![op(K::PushCondition,&[],Some(1))],body,vec![op(K::PopCondition,&[],None)]].concat()}
fn main(){let old=scoped(vec![ccx(0,1,5),cx(2,0),cx(2,5),cx(2,1),cx(5,3),cx(5,0),ccx(0,3,4),cx(5,0),cx(5,4),cx(5,3),cx(0,4),cx(0,3),cx(5,3),cx(2,5),cx(2,1),cx(2,0),op(K::Hmr,&[5],Some(0)),op(K::CZ,&[0,1],Some(0))]);let new=scoped(vec![cx(2,3),op(K::X,&[3],None),ccx(2,3,4),op(K::X,&[1],None),ccx(0,1,2),ccx(2,3,4),cx(2,3),op(K::X,&[3],None),ccx(0,1,2),op(K::X,&[1],None)]);let mut cases=0;
for data in 0..32{for flags in 0..16{let q:Vec<u64>=(0..8).map(|i|if i<5&&data>>i&1==1{u64::MAX}else{0}).collect();let word=|j|if flags>>j&1==1{u64::MAX}else{0};let a=run(&old,&q,word(0),word(1),word(2),word(3));let b=run(&new,&q,word(0),word(1),word(2),word(3));assert_eq!(a.0,b.0);assert_eq!(a.2,b.2);assert_eq!(a.2,word(2));assert_eq!(a.3,1);assert_eq!(b.3,0);cases+=1;}}
// Deliberately nontrivial interior: quantum writes, phases, conditional classical state,
// nested snapshot scopes, and two internal measurements. Borrowed C is absent;
// A/B and Z are never written. This supplements the universal renaming induction.
let interior=vec![op(K::X,&[3],None),cx(5,3),ccx(5,3,4),op(K::Hmr,&[4],Some(2)),op(K::CZ,&[5,3],None),op(K::X,&[7],Some(2)),op(K::PushCondition,&[],Some(2)),cx(5,6),op(K::PopCondition,&[],None),op(K::Hmr,&[6],Some(3)),op(K::CCZ,&[5,3,7],Some(3))];let mut oi=vec![ccx(0,1,5),cx(2,5)];oi.extend(interior.clone());oi.extend([cx(2,5),op(K::Hmr,&[5],Some(0)),op(K::CZ,&[0,1],Some(0))]);let oi=scoped(oi);let mut ni=vec![ccx(0,1,2)];for mut o in interior{for q in [&mut o.q_control1,&mut o.q_control2,&mut o.q_target]{if q.0==5{q.0=2;}}o.validate();ni.push(o);}ni.push(ccx(0,1,2));let ni=scoped(ni);let mut seed=0x1527abcedu64;let mut borrow_cases=0;
for _ in 0..1024{let mut next=||{seed^=seed<<13;seed^=seed>>7;seed^=seed<<17;seed};let mut q:Vec<_>=(0..8).map(|_|next()).collect();q[5]=0;let(m,base,phase,mr)=(next(),next(),next(),next());let a=run(&oi,&q,m,base,phase,mr);let b=run(&ni,&q,m,base,phase,mr);assert_eq!(a.0,b.0);assert_eq!(a.2,b.2);assert_eq!(a.1[1..],b.1[1..]);assert_eq!(a.3,3);assert_eq!(b.3,2);borrow_cases+=64;}
println!("{}",serde_json::json!({"status":"PROTECTED_SIMULATOR_PRIMITIVE_PASS","four_toffoli_exhaustive_cases":cases,"borrowed_carry_random_bitparallel_cases":borrow_cases,"borrowed_generic_proof":"C is unreferenced, A/B/Z unwritten in interior, so Z->C preserves every interior input; inverse CCX restores C, final original HMR/CZ phase cancels for arbitrary m; removed classical bit separately proven dead", "not_claimed":["Q1233","fullsourceequivalence","allhighwirecoverage"]}));}
